    const btns=x=>'<button class="btn btn-g btn-sm" onclick="VRTParts39.editStock(\''+kind+'\',\''+x.id+'\')">'+t('btnEdit')+'</button> <button class="btn btn-g btn-sm" onclick="VRTParts39.daily(\''+kind+'\',\''+x.id+'\')">'+L('日明細','Daily','ថ្ងៃ')+'</button> <button class="btn btn-r btn-sm" onclick="VRTParts39.deleteStock(\''+kind+'\',\''+x.id+'\')">'+t('btnDel')+'</button>';
