  g.VRTParts39.deleteStock=async function(kind,id){const r=reportFor(kind);if(!r||!confirm(L('刪除本期此品項？修改前的資料保留於歷史。','Delete this item from the period? The previous version is kept in history.','លុបមុខទំនិញនេះ?')))return;r.history=r.history||[];r.history.push({updatedAt:r.updatedAt,items:C.copy(r.items),fingerprint:r.fingerprint});r.deletedItemIds=[...new Set([...(r.deletedItemIds||[]),id])];r.items=r.items.filter(x=>x.id!==id);r.updatedAt=new Date().toISOString();r.fingerprint=C.hash(r.items);await saveAll();renderStockReport(kind)};
