  g.VRTParts39.saveChange=async id=>{try{const r={};for(const k of ['date','needleType','size','line','machine','operator','reason','remark'])r[k]=$('v39-'+k).value.trim();r.qty=n($('v39-qty').value);r.returned=n($('v39-returned').value);validateChange(r);r.reasonClass=g.VRTImport40&&g.VRTImport40.reasonClass?g.VRTImport40.reasonClass(r.reason):undefined;const list=g.VRTParts39.changeKind==='part'?M.partChanges:M.needleChanges;if(g.VRTParts39.changeKind==='part'){r.partType=r.needleType;delete r.needleType}const old=list.find(x=>x.id===id),stamp=new Date().toISOString();r.id=old?.id||'NC-'+crypto.randomUUID();r.createdAt=old?.createdAt||stamp;r.updatedAt=stamp;if(old){M.editHistory.push({id:'NCH-'+C.hash(old),record:C.copy(old),at:stamp});Object.assign(old,r)}else list.push(r);await saveAll();closeModal();renderChanges(g.VRTParts39.changeKind==='part')}catch(err){toast(err.message)}};
