  function analyticsRows(){const kind=analytics.kind,list=kind==='needle'?M.needleChanges:kind==='part'?M.partChanges:[...M.needleChanges,...M.partChanges];return list.filter(r=>inDateRange(r.date)&&(!FILTER.q||C.norm([r.needleType,r.partType,r.size,r.line,r.reason].join(' ')).includes(C.norm(FILTER.q))))}
