    h+='<div class="kpi-strip">'+kpi(fmt(total)+'<span class="kpi-u"> '+unit+'</span>',L('本期更換合計','Total changed','សរុប'),'k-blue')+kpi(fmt(changeover),L('換款（計畫）','Change style (planned)','ប្តូរម៉ូដ'),'k-slate',pct(changeover))+kpi(fmt(unplanned),L('損壞＋斷針（非計畫）','Damage + broken (unplanned)','ខូច+បាក់'),'k-red',pct(unplanned))+kpi(fmt(unknown+(reasons.find(x=>x.key==='other')?.qty||0)+(reasons.find(x=>x.key==='lost')?.qty||0)),L('其他／未填','Other / blank','ផ្សេងៗ'),'k-amber')+kpi(fmt(items.length),L('品項數','Items','មុខ'),'k-violet',items[0]?L('最多','Top','ខ្ពស់បំផុត')+'：'+e(items[0].key)+' '+fmt(items[0].qty):'')+kpi(fmt(lines.filter(l=>!/Unassigned/.test(l.key)).length),L('涉及線別','Lines','ខ្សែ'),'k-green',(lines.slice().sort((a,b)=>b.qty-a.qty)[0]?L('最多','Top','ខ្ពស់បំផុត')+'：'+shortLine(lines.slice().sort((a,b)=>b.qty-a.qty)[0].key)+' '+fmt(lines.slice().sort((a,b)=>b.qty-a.qty)[0].qty):''))+'</div>';
