    h+='<div class="card"><div class="ct">🎯 '+L('原因分類','Reason classes','ចំណាត់ថ្នាក់មូលហេតុ')+'</div><div class="tw"><table><thead><tr><th>'+L('分類','Class','ថ្នាក់')+'</th><th>'+L('數量','Qty','ចំនួន')+'</th><th class="num">%</th><th>'+L('說明','Note','ចំណាំ')+'</th></tr></thead><tbody>'+reasons.map(x=>'<tr><td><b>'+reasonLabel(x.key)+'</b></td><td style="min-width:140px">'+bar(x.qty,Math.max(1,reasons[0].qty),x.key==='changeover'?'#64748b':['damage','broken'].includes(x.key)?'#ef4444':'#f59e0b')+'</td><td class="num">'+pct(x.qty)+'</td><td style="font-size:12px;color:var(--sub)">'+({changeover:L('換款準備，屬正常消耗','Changeover preparation; normal consumption','ការប្តូរម៉ូដ'),damage:L('損壞，應追機台／操作原因','Damage — investigate machine / handling','ខូច'),broken:L('斷針，應追機台／布料／針型','Broken — investigate machine / fabric / needle type','បាក់'),lost:L('遺失','Lost','បាត់'),other:L('原表寫其他','Marked other in source','ផ្សេងៗ'),unknown:L('原表未填原因，請提醒機修填寫','No reason in source; ask maintenance to fill it in','មិនបានបំពេញ')}[x.key]||'')+'</td></tr>').join('')+'</tbody></table></div></div></div>';
    const maxI=Math.max(1,items[0]?.qty||1);
    h+='<div class="card"><div class="ct">🏆 '+L('品項排行（哪種換最多）','Item ranking (most changed)','ចំណាត់ថ្នាក់មុខទំនិញ')+'</div><div class="tw"><table class="v39-table"><thead><tr><th>#</th><th>'+L('品項／尺寸','Item / size','មុខ/ទំហំ')+'</th><th>'+L('合計','Total','សរុប')+'</th><th class="num">%</th><th class="num">'+L('換款','Style','ម៉ូដ')+'</th><th class="num">'+L('損壞','Damage','ខូច')+'</th><th class="num">'+L('斷針','Broken','បាក់')+'</th><th class="num">'+L('其他','Other','ផ្សេង')+'</th><th>'+L('主要線別','Top lines','ខ្សែសំខាន់')+'</th><th class="num">'+L('天數','Days','ថ្ងៃ')+'</th></tr></thead><tbody>'+items.slice(0,40).map((x,i)=>{const byLine=groupBy(x.rows,r=>r.line).sort((a,b)=>b.qty-a.qty).slice(0,3),dmg=x.rows.filter(r=>rc(r)==='damage').reduce((s,r)=>s+r.qty,0),brk=x.rows.filter(r=>rc(r)==='broken').reduce((s,r)=>s+r.qty,0);return '<tr><td>'+(i+1)+'</td><td>'+e(x.key)+'</td><td style="min-width:150px">'+bar(x.qty,maxI,x.unplanned>x.changeover?'#ef4444':'#0ea5e9')+'</td><td class="num">'+pct(x.qty)+'</td><td class="num">'+fmt(x.changeover)+'</td><td class="num">'+fmt(dmg)+'</td><td class="num">'+fmt(brk)+'</td><td class="num">'+fmt(x.other)+'</td><td>'+e(byLine.map(l=>shortLine(l.key)+':'+l.qty).join(' '))+'</td><td class="num">'+new Set(x.rows.map(r=>r.date)).size+'</td></tr>'}).join('')+'</tbody></table></div>'+(items.length>40?'<p style="font-size:12px;color:var(--sub)">'+L('只顯示前 40 項，匯出可得全部。','Top 40 shown; export for all.','បង្ហាញ 40 ដំបូង')+'</p>':'')+'</div>';
