  g.VRTParts39.analyticsKind=k=>{analytics.kind=k;renderChangeAnalytics()};
  function purchaseInsights(periodText){const all=purchaseTxns().filter(x=>inDateRange(x.date||((x.statementMonth||'')+'-01')));if(!all.length)return '';
    const by={};all.forEach(x=>{const k=x.partNo||x.name||'--',o=by[k]||(by[k]={key:k,name:x.name||PARTS.find(p=>p.partNo===x.partNo)?.name||'',qty:0,spend:0,rows:[],units:new Set()});o.rows.push(x);o.qty+=Number(x.qty)||0;o.spend+=purchaseAmount(x);o.units.add(C.partUnit(x.unit))});
    const list=Object.values(by),topQty=list.slice().sort((a,b)=>b.qty-a.qty).slice(0,10),topSpend=list.slice().sort((a,b)=>b.spend-a.spend).slice(0,10),spend=all.reduce((s,x)=>s+purchaseAmount(x),0);
    // Anomalies: price jump vs previous purchase of the same part/unit, duplicate invoice lines, quantity spike vs the part's median.
    const anomalies=[];const byPartUnit={};purchaseTxns().forEach(x=>{const k=(x.partNo||x.name)+'|'+C.partUnit(x.unit);(byPartUnit[k]||(byPartUnit[k]=[])).push(x)});
    for(const x of all){const k=(x.partNo||x.name)+'|'+C.partUnit(x.unit),hist=(byPartUnit[k]||[]).filter(y=>y.unitPrice>0).sort((a,b)=>String(a.date||'').localeCompare(String(b.date||''))),i=hist.indexOf(x),prev=i>0?hist[i-1]:null;
      if(prev&&prev.unitPrice&&x.unitPrice&&Math.abs(x.unitPrice-prev.unitPrice)/prev.unitPrice>0.2)anomalies.push({x,type:L('單價異常','Price change','តម្លៃ'),detail:money(prev.unitPrice)+' → '+money(x.unitPrice)+' ('+((x.unitPrice-prev.unitPrice)/prev.unitPrice*100).toFixed(0)+'%) · '+e(prev.date||'')});
      const qs=(byPartUnit[k]||[]).map(y=>Number(y.qty)||0).filter(q=>q>0).sort((a,b)=>a-b),med=qs.length?qs[Math.floor(qs.length/2)]:0;if(qs.length>=4&&med&&x.qty>med*3)anomalies.push({x,type:L('數量異常','Quantity spike','ចំនួន'),detail:fmt(x.qty)+' vs '+L('中位','median','មធ្យម')+' '+fmt(med)});
      const dup=all.filter(y=>y!==x&&C.norm(y.invoiceNo)===C.norm(x.invoiceNo)&&C.norm(y.partNo||y.name)===C.norm(x.partNo||x.name)&&Number(y.qty)===Number(x.qty)&&Number(y.unitPrice)===Number(x.unitPrice));if(dup.length&&all.indexOf(x)<all.indexOf(dup[0]))anomalies.push({x,type:L('疑似重複','Possible duplicate','ស្ទួន'),detail:L('同發票、同料號、同數量單價','Same invoice, part, qty and price','ដូចគ្នា')})}
    let h='<div class="card"><div class="ct">💰 '+L('採購重點','Purchase insights','ចំណុចទិញ')+' · '+e(periodText)+' · '+money(spend)+'</div><div class="g2"><div><b>'+L('採購量最多 Top 10','Top 10 by quantity','ចំនួនច្រើនបំផុត')+'</b><div class="tw"><table><thead><tr><th>'+t('colPartNo')+'</th><th>'+t('colName')+'</th><th class="num">'+L('數量','Qty','ចំនួន')+'</th><th class="num">'+L('金額','Amount','ទឹកប្រាក់')+'</th></tr></thead><tbody>'+topQty.map(o=>'<tr><td class="mono">'+e(o.key)+'</td><td>'+e(o.name)+'</td><td class="num">'+purchaseQuantityText43(o.rows)+'</td><td class="num">'+money(o.spend)+'</td></tr>').join('')+'</tbody></table></div></div><div><b>'+L('採購金額最多 Top 10','Top 10 by spend','ចំណាយច្រើនបំផុត')+'</b><div class="tw"><table><thead><tr><th>'+t('colPartNo')+'</th><th>'+t('colName')+'</th><th class="num">'+L('金額','Amount','ទឹកប្រាក់')+'</th><th class="num">%</th></tr></thead><tbody>'+topSpend.map(o=>'<tr><td class="mono">'+e(o.key)+'</td><td>'+e(o.name)+'</td><td class="num">'+money(o.spend)+'</td><td class="num">'+(spend?(o.spend/spend*100).toFixed(0)+'%':'—')+'</td></tr>').join('')+'</tbody></table></div></div></div>';
    h+='<div style="margin-top:10px"><b>'+L('採購異常','Purchase anomalies','ការទិញមិនប្រក្រតី')+' · '+anomalies.length+'</b>'+(anomalies.length?'<div class="tw"><table><thead><tr><th>'+t('colDate')+'</th><th>'+L('發票','Invoice','វិក្កយបត្រ')+'</th><th>'+t('colPartNo')+'</th><th>'+t('colName')+'</th><th>'+L('類型','Type','ប្រភេទ')+'</th><th>'+L('說明','Detail','ព័ត៌មាន')+'</th><th>'+t('colSupplier')+'</th></tr></thead><tbody>'+anomalies.slice(0,50).map(a=>'<tr><td class="mono">'+e(a.x.date||'')+'</td><td class="mono">'+e(a.x.invoiceNo||'')+'</td><td class="mono">'+e(a.x.partNo||'')+'</td><td>'+e(a.x.name||'')+'</td><td><span class="b '+(a.type.includes('重複')||/duplicate/i.test(a.type)?'bwn':'bbd')+'">'+a.type+'</span></td><td>'+a.detail+'</td><td>'+e(a.x.supplier||'')+'</td></tr>').join('')+'</tbody></table></div>':'<p style="font-size:12px;color:var(--sub)">'+L('本期沒有偵測到單價跳動 >20%、數量超過中位數 3 倍或重複發票列。','No price change >20%, quantity above 3× median, or duplicate invoice lines in this period.','គ្មានភាពមិនប្រក្រតី')+'</p>')+'</div></div>';return h}
  g.VRTParts39.exportAnalytics=asCsv=>{const rows=analyticsRows();if(!rows.length)return toast(t('noData'));const itemKey=r=>(r.needleType||r.partType)+' '+r.size,items=groupBy(rows,itemKey).sort((a,b)=>b.qty-a.qty).map(x=>({Item:x.key,Total:x.qty,'Change Style':x.changeover,Unplanned:x.unplanned,Other:x.other,Days:new Set(x.rows.map(r=>r.date)).size})),lines=groupBy(rows,r=>r.line).sort((a,b)=>lineSort(a.key,b.key)).map(x=>({Line:x.key,Total:x.qty,'Change Style':x.changeover,Unplanned:x.unplanned,Other:x.other})),days=groupBy(rows,r=>r.date).sort((a,b)=>a.key.localeCompare(b.key)).map(x=>({Date:x.key,Total:x.qty,'Change Style':x.changeover,Unplanned:x.unplanned,Other:x.other})),detail=rows.map(r=>({Date:r.date,Item:r.needleType||r.partType,Size:r.size,Line:r.line,Qty:r.qty,Reason:r.reason,'Reason Class':rc(r),Source:r.sourceFile||'',Sheet:r.sourceSheet||''}));const name='VRT_Change_Analytics_'+(FILTER.periodKey||'all');if(asCsv)return csv(detail,name+'.csv');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(items),'By Item');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(lines),'By Line');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(days),'By Day');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(detail),'Detail');XLSX.writeFile(wb,name+'.xlsx')};

  exportExcel=function(){const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sheetData()),'Inventory');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(TXNS.map(x=>({'Record ID':x.id,Date:x.date,'Invoice No':x.invoiceNo,'Part No':x.partNo,'Standard Name':x.name,Qty:x.qty,Unit:x.unit,'Unit Price':x.unitPrice,'Calculated Amount':purchaseAmount(x),'Statement Month':x.statementMonth,Type:x.type,Supplier:x.supplier,Spec:x.spec,Category:x.category,Brand:x.brand,'Machine / Use':x.machineType,'Include in Master':x.includeInMaster===false?'No':'Yes',Notes:x.remark,'Source File':x.sourceFile,'Source Sheet':x.sourceSheet,'Source Row':x.sourceRow}))), 'Transaction Detail');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(M.stockReports.flatMap(stockRows)),'Stock Snapshots');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(changeRows(),{header:['Record ID','Date','Needle Type','Size','Line','Machine','Operator','Reason','Reason Class','Qty','Returned','Remark']}),'Needle Change');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(changeRows(true)),'Part Change');XLSX.writeFile(wb,'VRT_Maintenance_v413_'+todayStr()+'.xlsx')};
