  restoreLocal=async function(file){if(!file)return;try{const d=JSON.parse(await file.text());if(!Array.isArray(d.parts)&&!d.maintenance39)throw new Error(L('不是有效備份','Not a valid backup','មិនមែនជាឯកសារបម្រុង'));PARTS=D.mergeRows(PARTS,d.parts,r=>C.norm(r.partNo));TXNS=D.mergeRows(TXNS,d.txns);VERSIONS=D.mergeRows(VERSIONS,d.versions);SUPPLIERS=D.mergeRows(SUPPLIERS,d.suppliers);INVOICES=D.mergeRows(INVOICES,d.invoices);OCRHIST=D.mergeRows(OCRHIST,d.ocrhist);SET={...SET,...d.settings};M=D.mergeMaintenance(M,d.maintenance39);await saveAll(true);goTab(_curTab)}catch(err){toast(err.message)}};
  cloudUpload=async function(silent){const url=g.VRTPlatform?.getGasUrl()||SET.gasUrl;if(!url){g.VRTSmartSync.status('push',L('請先設定 GAS URL','Set the GAS URL first','សូមកំណត់ GAS URL'),'warn');return false}try{await saveAll(false);return await D.sync('spareparts','push',url,m=>{if(!silent)toast(m)},{network:{vrtTimeoutMs:90000,vrtRetryDelays:[5000,15000,45000]},resumeBuckets:true,priorityBuckets:['ie_tombstones','maintenance_tombstones']})}catch(err){g.VRTSmartSync.status('push',err.message,'err');throw err}};
