  savePart=async function(id){try{const get=k=>$('m_'+k).value.trim(),code=get('partNo');if(!code||!get('name'))throw new Error(L('請填料號及品名','Enter part no. and name','សូមបំពេញលេខកូដ និងឈ្មោះ'));if(PARTS.some(p=>p.id!==id&&C.norm(p.partNo)===C.norm(code)))throw new Error(L('料號已存在，請編輯原品項','Part no. already exists; edit that item','មានលេខកូដរួច'));const old=PARTS.find(x=>x.id===id),row={...old,partNo:code,name:get('name'),spec:get('spec'),category:get('cat'),brand:get('brand'),machineType:get('mt'),location:get('loc'),unit:get('unit'),remark:get('remark')};for(const [field,key] of [['qty','qty'],['unitPrice','price'],['minStock','min'],['maxStock','max']]){row[field]=n(get(key));if(row[field]!=null&&row[field]<0)throw new Error(L('數量／單價不可為負數','Quantity / price cannot be negative','មិនអាចអវិជ្ជមាន'))}const stamp=new Date().toISOString();row.id=old?.id||'PART-'+crypto.randomUUID();row.createdAt=old?.createdAt||stamp;row.updatedAt=stamp;row.purchaseOnly=false;if(old){M.editHistory.push({id:'PARTH-'+C.hash(old),record:C.copy(old),at:stamp});Object.assign(old,row)}else PARTS.push(row);await saveAll();closeModal();renderInventory()}catch(err){toast(err.message)}};
  // Statement periods drive purchase totals; invoice dates remain visible separately.
