  latestPurchaseMonth=()=>purchaseTxns().map(purchasePeriod).filter(Boolean).sort().pop()||todayStr().slice(0,7);
  latestPurchaseYear=()=>latestPurchaseMonth().slice(0,4);
  filteredTxns=()=>TXNS.filter(x=>{const p=PARTS.find(r=>r.partNo===x.partNo)||x;if(FILTER.cat&&p.category!==FILTER.cat||FILTER.store&&p.location!==FILTER.store||FILTER.brand&&p.brand!==FILTER.brand)return false;if(FILTER.q&&!C.norm([x.partNo,x.name,p.name,x.invoiceNo].join(' ')).includes(C.norm(FILTER.q)))return false;const period=purchasePeriod(x);if(FILTER.date==='year')return period.slice(0,4)===todayStr().slice(0,4);if(FILTER.date==='month')return period===todayStr().slice(0,7);return inDateRange(x.date)});
  renderHistory=function(){fillFilterSelects();const xs=filteredTxns().sort((a,b)=>(b.date||'').localeCompare(a.date||''));$('app').innerHTML='<div class="sec on"><div class="card"><div class="ct">🧾 '+L('採購／異動紀錄','Purchase / movement records','កំណត់ត្រាទិញ')+' · '+xs.length+' '+L('筆','rows','ជួរ')+'</div><button class="btn btn-y" onclick="VRTParts39.editPurchase()">＋ '+L('新增採購','Add purchase','បន្ថែមការទិញ')+'</button><div class="tw"><table class="v39-table"><thead><tr><th>'+L('對帳月份','Statement month','ខែ')+'</th><th>'+L('發票日期','Invoice date','ថ្ងៃវិក្កយបត្រ')+'</th><th>'+L('發票','Invoice','វិក្កយបត្រ')+'</th><th>'+L('料號／品名','Part no. / name','លេខកូដ/ឈ្មោះ')+'</th><th>'+t('colType')+'</th><th>'+L('數量／單位','Qty / unit','ចំនួន/ឯកតា')+'</th><th>'+t('colPrice')+'</th><th>'+L('金額','Amount','ទឹកប្រាក់')+'</th><th>'+t('colSupplier')+'</th><th>'+L('操作','Actions','សកម្មភាព')+'</th></tr></thead><tbody>'+xs.map(x=>'<tr><td>'+e(purchasePeriod(x))+'</td><td>'+e(x.date)+'</td><td>'+e(x.invoiceNo)+'</td><td>'+e(x.partNo)+'<br>'+e(x.name||PARTS.find(p=>p.partNo===x.partNo)?.name||'')+'</td><td>'+e(x.type||'PURCHASE')+'</td><td>'+fmt(x.qty)+' '+e(x.unit||'')+'</td><td>'+money(x.unitPrice)+'</td><td>'+money(purchaseAmount(x))+'</td><td>'+e(x.supplier)+'</td><td><button class="btn btn-g" onclick="VRTParts39.editPurchase(\''+x.id+'\')">'+t('btnEdit')+'</button> <button class="btn btn-r" onclick="delTxn(\''+x.id+'\')">'+t('btnDel')+'</button></td></tr>').join('')+'</tbody></table></div></div></div>'};
  const historyBase43=renderHistory;renderHistory=function(){historyBase43();const variants=PARTS.filter(p=>p.unitVariants?.length);if(variants.length)$('app').innerHTML+='<div class="card"><h3>'+L('不同單位的來源資料','Source rows in other units','ឯកតាផ្សេង')+'</h3><p>'+L('原庫存單位與數量保留；下列來源單位分開顯示，未自動換算。','Original stock unit and quantity are kept; other units are shown separately without conversion.','ឯកតាដើមរក្សាទុក។')+'</p>'+variants.map(p=>'<p>'+e(p.partNo)+' · '+L('原庫存','Stock','ស្តុក')+' '+fmt(p.qty)+' '+e(p.unit)+'；'+p.unitVariants.map(v=>e(v.unit)+' · '+(v.qty==null?L('價格主檔，無庫存數量','price master only','គ្មានចំនួន'):fmt(v.qty))+' · '+t('colPrice')+' '+fmt(v.unitPrice)).join(' / ')+'</p>').join('')+'</div>';const refs=M.invoiceSummaries||[];if(refs.length)$('app').innerHTML+='<div class="card"><h3>2024 '+L('發票摘要','Invoice summaries','សង្ខេបវិក្កយបត្រ')+' · '+refs.length+'</h3><p>'+L('摘要金額','Summary amount','ទឹកប្រាក់សង្ខេប')+' '+money(refs.reduce((n,r)=>n+r.amount,0))+'。'+L('上方採購含可辨識的部分明細；摘要獨立核對，不重複加總。','Purchases above hold the identifiable detail; summaries are checked separately and never double-counted.','មិនរាប់ស្ទួន។')+'</p><button class="btn btn-g" onclick="VRTParts39.exportInvoices()">'+L('匯出發票摘要','Export invoice summaries','នាំចេញ')+'</button><div class="tw"><table><thead><tr><th>'+t('colDate')+'</th><th>'+L('發票','Invoice','វិក្កយបត្រ')+'</th><th>'+t('colSupplier')+'</th><th>'+L('金額','Amount','ទឹកប្រាក់')+'</th><th>'+t('colRemark')+'</th></tr></thead><tbody>'+refs.map(r=>'<tr><td>'+e(r.date)+'</td><td>'+e(r.invoiceNo)+'</td><td>'+e(r.supplier)+'</td><td>'+money(r.amount)+'</td><td>'+e(r.notes)+'</td></tr>').join('')+'</tbody></table></div></div>'};
