  g.VRTParts39.editPurchase=id=>{const r=TXNS.find(x=>x.id===id)||{};openModal('<h3>'+L('採購紀錄','Purchase record','កំណត់ត្រាទិញ')+'</h3><div class="frm-grid">'+field('date',L('發票日期','Invoice date','ថ្ងៃវិក្កយបត្រ'),r.date||todayStr(),'date')+field('statementMonth',L('對帳月份 YYYY-MM','Statement month YYYY-MM','ខែ'),purchasePeriod(r)||todayStr().slice(0,7),'month')+field('invoiceNo',L('發票號碼','Invoice no.','លេខវិក្កយបត្រ'),r.invoiceNo)+field('partNo',t('colPartNo'),r.partNo)+field('name',t('colName'),r.name)+field('unit',t('colUnit'),r.unit||'PCS')+field('qty',L('數量','Qty','ចំនួន'),r.qty,'number')+field('unitPrice',t('colPrice'),r.unitPrice,'number')+field('supplier',t('colSupplier'),r.supplier)+field('remark',t('colRemark'),r.remark)+'</div><button class="btn btn-y" onclick="VRTParts39.savePurchase(\''+(id||'')+'\')">'+t('btnSave')+'</button> <button class="btn btn-g" onclick="closeModal()">'+t('btnCancel')+'</button>')};
  g.VRTParts39.savePurchase=async id=>{try{const old=TXNS.find(x=>x.id===id),r={...old};for(const k of ['date','statementMonth','invoiceNo','partNo','name','unit','supplier','remark'])r[k]=$('v39-'+k).value.trim();r.qty=n($('v39-qty').value);r.unitPrice=n($('v39-unitPrice').value);if(!r.date||!r.partNo||!r.name||!r.unit||r.qty==null||r.qty<0||r.unitPrice==null||r.unitPrice<0)throw new Error(L('請填日期、料號、品名、單位及有效數量／單價','Enter date, part no., name, unit and valid qty / price','សូមបំពេញឱ្យគ្រប់'));r.amount=r.qty*r.unitPrice;if(!old&&TXNS.some(x=>txKey(x)===txKey(r)))throw new Error(L('已有相同發票、料號、日期、數量與單價，請編輯原紀錄','Same invoice, part, date, qty and price exists; edit that record','មានរួចហើយ'));if(old)M.editHistory.push({id:'TXH-'+C.hash(old),record:C.copy(old),at:new Date().toISOString()});r.id=old?.id||'PUR-'+crypto.randomUUID();r.type=old?.type||'PURCHASE';r.updatedAt=new Date().toISOString();r.invoiceDate=r.date;if(old)Object.assign(old,r);else TXNS.push(r);await saveAll();closeModal();renderHistory()}catch(err){toast(err.message)}};
  const ensureMasterOriginal=ensurePurchasePartMaster;
